"""Triage customer support tickets with SubQ Snap (subq-snap-preview) via the Decisions API.

For each ticket, one request asks three independent questions:
  urgent   (noul)   - probability the ticket needs a response within the hour
  team     (choice) - billing / engineering / sales / other
  severity (score)  - 3 ordered levels: low / medium / high
Uncertain answers are flagged with needs_human=true and the reasons.

Input:  a .jsonl file with one {"id": ..., "text": ...} object per line,
        or a plain-text file with one ticket per line (ids are line numbers).
Output: one JSON object per ticket on stdout (or --out FILE), including raw probabilities
        so thresholds can be retuned without calling the API again.

Usage:
    export SUBQ_API_KEY=...        # never put the key in this file or on the command line
    python3 triage.py tickets.jsonl --out triaged.jsonl

The thresholds below are placeholders. Calibrate them on tickets you have already labelled.
Contract: https://docs.subq.ai/markdown/endpoints/decisions-api.md
"""

from __future__ import annotations

import argparse
import http.client
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

URL = "https://api.subq.ai/v1/systemone"
MODEL = "subq-snap-preview"

# Placeholder thresholds; tune per question on labelled tickets.
URGENT_YES = 0.70  # p(urgent) >= this -> urgent
URGENT_NO = 0.30  # p(urgent) <= this -> not urgent; in between -> human
MIN_TEAM_CONFIDENCE = 0.60
MIN_SEVERITY_CONFIDENCE = 0.50
MAX_TICKET_CHARS = 20_000  # tickets are short; trimming keeps cost and latency down

SEVERITY_LEVELS = ["low", "medium", "high"]

QUESTIONS = {
    "urgent": {
        "type": "noul",
        "instructions": "Read the customer support ticket in the state. Does it need a response within the hour?",
        "criteria": {
            "true": "Outage, data loss, security incident, account lockout or a blocked payment affecting the customer now",
            "false": "Questions, feature requests, minor bugs or anything that can wait until the next business day",
        },
    },
    "team": {
        "type": "choice",
        "instructions": "Read the customer support ticket in the state. Which team should own it?",
        "criteria": {
            "billing": "Charges, invoices, refunds, payment methods, failed or duplicate payments",
            "engineering": "Bugs, crashes, errors, outages, performance, integrations or API problems",
            "sales": "Pricing questions, plans, upgrades, quotes, new purchases or contract terms",
            "other": None,
        },
    },
    "severity": {
        "type": "score",
        "instructions": "Read the customer support ticket in the state. How severely is the customer affected?",
        "criteria": [
            "Low: a question, request or cosmetic issue; the customer can work normally",
            "Medium: something is broken or wrong but there is a workaround or limited impact",
            "High: the customer cannot use the product, is losing money or data, or security is at risk",
        ],
    },
}


class SnapError(Exception):
    def __init__(self, status: int | None, error_type: str, message: str) -> None:
        super().__init__(f"{status} {error_type}: {message}")
        self.status = status
        self.error_type = error_type


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    # urllib would resend the Authorization header to a redirect target; refuse instead.
    def redirect_request(self, req, fp, code, msg, headers, newurl):  # noqa: ANN001
        return None


_OPENER = urllib.request.build_opener(_NoRedirect)


def _error_detail(e: urllib.error.HTTPError) -> dict:
    try:
        payload = json.load(e)
    except ValueError:
        return {}
    detail = payload.get("detail") if isinstance(payload, dict) else None
    return detail if isinstance(detail, dict) else {"message": str(payload)[:200]}


def decide(key: str, state, questions: dict, *, attempts: int = 5, timeout_s: float = 60.0) -> dict:
    """One Decisions request with bounded retries on 429/5xx/network errors (exponential backoff, full jitter)."""
    data = json.dumps({"model": MODEL, "state": state, "questions": questions}).encode()
    headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
    for attempt in range(attempts):
        last = attempt == attempts - 1
        try:
            req = urllib.request.Request(URL, data=data, headers=headers, method="POST")
            with _OPENER.open(req, timeout=timeout_s) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            detail = _error_detail(e)
            if not (e.code == 429 or e.code >= 500) or last:
                raise SnapError(e.code, detail.get("error_type", "http_error"), detail.get("message", "")) from e
        except (OSError, http.client.HTTPException, ValueError) as e:
            # Timeouts, resets, truncated/invalid bodies: outcome unknown. Retrying is safe (no side effects).
            if last:
                raise SnapError(None, "network", f"{type(e).__name__}: {e}") from e
        time.sleep(random.uniform(0, min(30.0, 1.0 * 2**attempt)))
    raise SnapError(None, "internal", "retry loop ended without a result")


def _argmax_level(probabilities, n_levels: int) -> int | None:
    """Index of the most likely score level; accepts a list or a dict keyed by level text/index."""
    if isinstance(probabilities, list) and len(probabilities) == n_levels:
        return max(range(n_levels), key=lambda i: probabilities[i])
    if isinstance(probabilities, dict):
        criteria = QUESTIONS["severity"]["criteria"]
        scored = {}
        for k, p in probabilities.items():
            if k in criteria:
                scored[criteria.index(k)] = p
            elif str(k).isdigit() and int(k) < n_levels:
                scored[int(k)] = p
        if len(scored) == n_levels:
            return max(scored, key=scored.get)
    return None


def interpret(answers: dict) -> dict:
    """Turn raw answers into a triage decision plus reasons a human should look."""
    reasons = []

    p_urgent = float(answers["urgent"]["noul"])
    if p_urgent >= URGENT_YES:
        urgent = True
    elif p_urgent <= URGENT_NO:
        urgent = False
    else:
        urgent = None
        reasons.append(f"urgency unclear (p={p_urgent:.2f})")

    team_ans = answers["team"]
    team = team_ans["choice"]
    team_conf = float(team_ans["confidence"])
    if team_conf < MIN_TEAM_CONFIDENCE:
        reasons.append(f"team uncertain ({team}, confidence={team_conf:.2f})")
    if team == "other":
        reasons.append("no matching team")

    sev_ans = answers["severity"]
    sev_conf = float(sev_ans["confidence"])
    idx = _argmax_level(sev_ans.get("probabilities"), len(SEVERITY_LEVELS))
    severity = SEVERITY_LEVELS[idx] if idx is not None else None
    if severity is None:
        reasons.append("could not read severity probabilities")
    elif sev_conf < MIN_SEVERITY_CONFIDENCE:
        reasons.append(f"severity uncertain ({severity}, confidence={sev_conf:.2f})")

    # Cheap consistency check: an urgent ticket rated low severity (or vice versa) deserves a look.
    if urgent is True and severity == "low":
        reasons.append("urgent but low severity")
    if urgent is False and severity == "high":
        reasons.append("high severity but not urgent")

    return {
        "urgent": urgent,
        "team": team,
        "severity": severity,
        "needs_human": bool(reasons),
        "reasons": reasons,
    }


def load_tickets(path: str) -> list[dict]:
    tickets = []
    with open(path, encoding="utf-8") as f:
        for n, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            if path.endswith(".jsonl"):
                obj = json.loads(line)
                tickets.append({"id": obj.get("id", n), "text": str(obj["text"])})
            else:
                tickets.append({"id": n, "text": line})
    return tickets


def main() -> int:
    parser = argparse.ArgumentParser(description="Triage support tickets with SubQ Snap.")
    parser.add_argument("tickets", help=".jsonl with {id, text} per line, or plain text with one ticket per line")
    parser.add_argument("--out", help="write JSONL results here instead of stdout")
    args = parser.parse_args()

    key = os.environ.get("SUBQ_API_KEY")
    if not key:
        print("SUBQ_API_KEY is not set", file=sys.stderr)
        return 2

    tickets = load_tickets(args.tickets)
    out = open(args.out, "w", encoding="utf-8") if args.out else sys.stdout
    total_tokens = flagged = failed = 0
    try:
        for t in tickets:
            record = {"id": t["id"]}
            state = {"ticket": t["text"][:MAX_TICKET_CHARS]}
            started = time.perf_counter()
            try:
                result = decide(key, state, QUESTIONS)
                record.update(interpret(result["answers"]))
                record["raw"] = result["answers"]
                record["input_tokens"] = result.get("usage", {}).get("input_tokens")
                total_tokens += record["input_tokens"] or 0
            except SnapError as e:
                if e.status in (401, 402, 403):
                    # Bad key, no credits or no model access: every further request would fail too.
                    print(f"fatal: {e}", file=sys.stderr)
                    return 1
                # 400/422, exhausted retries: this ticket goes to a human; continue with the rest.
                failed += 1
                record.update({"urgent": None, "team": None, "severity": None,
                               "needs_human": True, "reasons": [f"api error: {e}"]})
            except (KeyError, TypeError, ValueError) as e:
                failed += 1
                record.update({"urgent": None, "team": None, "severity": None,
                               "needs_human": True, "reasons": [f"unexpected response: {e!r}"]})
            record["latency_ms"] = round((time.perf_counter() - started) * 1000)
            flagged += record["needs_human"]
            out.write(json.dumps(record) + "\n")
            out.flush()
    finally:
        if out is not sys.stdout:
            out.close()

    print(f"{len(tickets)} tickets, {flagged} flagged for a human ({failed} errors), "
          f"{total_tokens} input tokens (~${total_tokens * 0.05 / 1e6:.4f})", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Triage customer support tickets with SubQ's Snap decision model.

For each ticket, one request to the SubQ Decisions API asks three questions:
  urgent    (noul)   -> probability the ticket is urgent
  team      (choice) -> billing | engineering | sales | other
  severity  (score)  -> low | medium | high

Results with low confidence, or tickets that could not be classified at all,
are marked needs_human=true with a list of reasons.

Input:  JSONL ({"id": ..., "text": ...} per line), a JSON array of the same,
        or plain text with one ticket per line. Use "-" for stdin.
Output: one JSON object per ticket on stdout (JSONL).

Usage:  SUBQ_API_KEY=... python triage.py tickets.jsonl > triaged.jsonl
"""

import argparse
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

API_URL = "https://api.subq.ai/v1/systemone"
MODEL = "subq-snap-preview"

# Uncertainty thresholds: anything inside these bands goes to a human.
URGENT_UNSURE_BAND = (0.3, 0.7)  # P(urgent) in this range is ambiguous
MIN_CHOICE_CONFIDENCE = 0.6
MIN_SCORE_CONFIDENCE = 0.6

MAX_ATTEMPTS = 5
BASE_BACKOFF_S = 1.0
MAX_BACKOFF_S = 30.0
TIMEOUT_S = 60

SEVERITY_LEVELS = ["low", "medium", "high"]

QUESTIONS = {
    "urgent": {
        "type": "noul",
        "instructions": "Does this support ticket need a response urgently (within hours, not days)?",
        "criteria": {
            "true": "Service outage, data loss, security issue, customer blocked from working, "
                    "payment failure preventing use, or explicit hard deadline.",
            "false": "General questions, feature requests, minor bugs with workarounds, "
                     "non-blocking billing questions.",
        },
    },
    "team": {
        "type": "choice",
        "instructions": "Which team should own this support ticket?",
        "criteria": {
            "billing": "Invoices, charges, refunds, payment methods, subscription plan changes.",
            "engineering": "Bugs, errors, outages, performance, integrations, API or technical problems.",
            "sales": "Pricing inquiries, upgrades for new capacity, quotes, demos, new contracts.",
            "other": "Anything that does not clearly fit billing, engineering, or sales.",
        },
    },
    "severity": {
        "type": "score",
        "instructions": "How severe is the impact of this issue on the customer?",
        "criteria": [
            "Low: cosmetic, question, or minor inconvenience",
            "Medium: degraded functionality or a workaround exists",
            "High: customer is blocked, data loss, security, or widespread outage",
        ],
    },
}


class FatalAPIError(Exception):
    """Errors that will affect every request (auth, credits, model access): abort the run."""


class TicketError(Exception):
    """Errors specific to one ticket (bad input, too long, retries exhausted)."""


def load_tickets(path):
    f = sys.stdin if path == "-" else open(path, encoding="utf-8")
    with f:
        raw = f.read()
    stripped = raw.strip()
    if stripped.startswith("["):
        items = json.loads(stripped)
    else:
        items = []
        for line in raw.splitlines():
            if not line.strip():
                continue
            try:
                items.append(json.loads(line))
            except json.JSONDecodeError:
                items.append(line.strip())
    tickets = []
    for i, item in enumerate(items, 1):
        if isinstance(item, dict):
            tickets.append({"id": item.get("id", i), "text": str(item.get("text", ""))})
        else:
            tickets.append({"id": i, "text": str(item)})
    return tickets


def _retry_delay(attempt, retry_after):
    if retry_after:
        try:
            return min(float(retry_after), MAX_BACKOFF_S)
        except ValueError:
            pass
    delay = min(BASE_BACKOFF_S * 2 ** (attempt - 1), MAX_BACKOFF_S)
    return delay * random.uniform(0.5, 1.0)  # jitter


def _error_message(body):
    try:
        detail = json.loads(body).get("detail", {})
        if isinstance(detail, dict):
            return f"{detail.get('error_type', 'error')}: {detail.get('message', '')}"
        return str(detail)
    except (ValueError, AttributeError):
        return body[:500]


def call_snap(api_key, ticket_text):
    payload = json.dumps({
        "model": MODEL,
        "state": {"ticket": ticket_text},
        "questions": QUESTIONS,
    }).encode("utf-8")
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }

    for attempt in range(1, MAX_ATTEMPTS + 1):
        req = urllib.request.Request(API_URL, data=payload, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=TIMEOUT_S) as resp:
                return json.loads(resp.read().decode("utf-8"))
        except urllib.error.HTTPError as e:
            msg = _error_message(e.read().decode("utf-8", errors="replace"))
            if e.code in (401, 402, 403):
                # Bad key, no credits, or no access to the model: no point continuing.
                raise FatalAPIError(f"HTTP {e.code}: {msg}") from e
            if e.code in (400, 422):
                # Input problem (e.g. ticket too long, invalid request): don't retry.
                raise TicketError(f"HTTP {e.code}: {msg}") from e
            if e.code == 429 or e.code >= 500:
                if attempt == MAX_ATTEMPTS:
                    raise TicketError(f"HTTP {e.code} after {attempt} attempts: {msg}") from e
                delay = _retry_delay(attempt, e.headers.get("Retry-After"))
                print(f"  HTTP {e.code}, retrying in {delay:.1f}s ({attempt}/{MAX_ATTEMPTS})",
                      file=sys.stderr)
                time.sleep(delay)
                continue
            raise TicketError(f"HTTP {e.code}: {msg}") from e
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            if attempt == MAX_ATTEMPTS:
                raise TicketError(f"network error after {attempt} attempts: {e}") from e
            delay = _retry_delay(attempt, None)
            print(f"  network error ({e}), retrying in {delay:.1f}s ({attempt}/{MAX_ATTEMPTS})",
                  file=sys.stderr)
            time.sleep(delay)
        except json.JSONDecodeError as e:
            raise TicketError(f"invalid JSON in response: {e}") from e
    raise TicketError("retries exhausted")  # unreachable


def interpret(answers):
    reasons = []

    urgent_ans = answers.get("urgent") or {}
    team_ans = answers.get("team") or {}
    sev_ans = answers.get("severity") or {}

    p_urgent = urgent_ans.get("noul")
    if p_urgent is None:
        urgent = None
        reasons.append("missing urgency answer")
    else:
        urgent = p_urgent >= 0.5
        lo, hi = URGENT_UNSURE_BAND
        if lo < p_urgent < hi:
            reasons.append(f"urgency ambiguous (p={p_urgent:.2f})")

    team = team_ans.get("choice")
    team_conf = team_ans.get("confidence")
    if team is None:
        reasons.append("missing team answer")
    elif team_conf is not None and team_conf < MIN_CHOICE_CONFIDENCE:
        reasons.append(f"team uncertain (confidence={team_conf:.2f})")

    sev_score = sev_ans.get("score")
    sev_conf = sev_ans.get("confidence")
    severity = None
    if sev_score is None:
        reasons.append("missing severity answer")
    else:
        idx = max(0, min(len(SEVERITY_LEVELS) - 1, round(sev_score)))
        severity = SEVERITY_LEVELS[idx]
        if sev_conf is not None and sev_conf < MIN_SCORE_CONFIDENCE:
            reasons.append(f"severity uncertain (confidence={sev_conf:.2f})")

    # Cross-check: contradictory signals deserve a second look.
    if urgent is True and severity == "low":
        reasons.append("marked urgent but severity low")
    if urgent is False and severity == "high":
        reasons.append("high severity but not marked urgent")

    return {
        "urgent": urgent,
        "urgent_probability": p_urgent,
        "team": team,
        "team_confidence": team_conf,
        "team_probabilities": team_ans.get("probabilities"),
        "severity": severity,
        "severity_score": sev_score,
        "severity_confidence": sev_conf,
        "needs_human": bool(reasons),
        "review_reasons": reasons,
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("tickets", help="tickets file (JSONL, JSON array, or plain lines); '-' for stdin")
    args = parser.parse_args()

    api_key = os.environ.get("SUBQ_API_KEY")
    if not api_key:
        sys.exit("SUBQ_API_KEY is not set")

    tickets = load_tickets(args.tickets)
    flagged = 0
    for n, ticket in enumerate(tickets, 1):
        print(f"[{n}/{len(tickets)}] ticket {ticket['id']}", file=sys.stderr)
        result = {"id": ticket["id"]}
        if not ticket["text"].strip():
            result.update(needs_human=True, review_reasons=["empty ticket"])
        else:
            try:
                resp = call_snap(api_key, ticket["text"])
                result.update(interpret(resp.get("answers", {})))
            except TicketError as e:
                result.update(needs_human=True, review_reasons=[f"API error: {e}"])
            except FatalAPIError as e:
                sys.exit(f"Aborting after {n - 1} ticket(s): {e}")
        flagged += result["needs_human"]
        print(json.dumps(result), flush=True)

    print(f"Done: {len(tickets)} tickets, {flagged} flagged for human review.", file=sys.stderr)


if __name__ == "__main__":
    main()
